(function(){
'use strict';
const I18N=(typeof ArtifactI18n!=='undefined'?ArtifactI18n:null)||(typeof require==='function'?(function(){try{return require('./i18n.js')}catch(e){return null}})():null);
const T=I18N?I18N.T:(z,e)=>z,cardName=I18N?I18N.cardName:c=>c?c.name:'',pick=I18N?I18N.pick:(o,b)=>o?o[b]:'';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let active=null;
function open(title){
 if(active)active.close();
 if(!document.getElementById('deck-share-style')){const style=document.createElement('style');style.id='deck-share-style';style.textContent='.deck-share-dialog{box-sizing:border-box;width:min(620px,94vw);max-height:90dvh;overflow:auto;background:#111b20;color:#ede8d6;border:1px solid #ac9360;padding:24px;font:16px/1.5 "Artifact KaiTi",system-ui;box-shadow:0 20px 80px #0009}.deck-share-dialog::backdrop{background:#000b}.deck-share-dialog h2{margin:0 0 12px}.deck-share-dialog p{font-size:14px}.deck-share-dialog input{box-sizing:border-box;width:100%;padding:12px;background:#080f14;color:#fff;border:1px solid #80704f;font:20px "Artifact KaiTi",monospace}.deck-share-dialog button{cursor:pointer;padding:10px 16px;min-height:44px;background:#293c40;color:#fff;border:1px solid #887650;font:inherit}.deck-share-dialog button:disabled{opacity:.5}.deck-share-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}.deck-share-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 20px;font-size:14px}.deck-share-dialog [role=status]{color:#ddc58d;min-height:21px}.deck-share-dialog .deck-share-code{letter-spacing:2px}.deck-share-dialog small{color:#bbb}@media(max-height:450px){.deck-share-dialog{padding:14px;max-height:96dvh}.deck-share-dialog h2{font-size:20px}}';document.head.append(style);}
 const d=document.createElement('dialog');d.className='deck-share-dialog';d.innerHTML=`<h2>${esc(title)}</h2><div data-body></div><p role="status" aria-live="polite"></p><div class="deck-share-actions" data-actions></div>`;document.body.append(d);active=d;d.addEventListener('close',()=>{d.remove();if(active===d)active=null;},{once:true});d.showModal();return d;
}
function action(d,label,fn){const b=document.createElement('button');b.textContent=label;b.type='button';b.onclick=fn;d.querySelector('[data-actions]').append(b);return b;}
function status(d,text){d.querySelector('[role=status]').textContent=text;}
async function request(path,options){const c=new AbortController(),timer=setTimeout(()=>c.abort(),15000);try{const r=await fetch(path,{...options,signal:c.signal});let data;try{data=await r.json();}catch{throw Error(T('此服务暂未提供构筑分享功能，请使用 JSON 导入导出。','Deck sharing is not available on this server — use JSON import/export.'));}if(!r.ok)throw Error(data.error||data.message||T('分享请求失败，请稍后重试。','Share request failed — please retry.'));return data;}catch(e){if(e.name==='AbortError'||e instanceof TypeError)throw Error(T('无法连接分享服务，请检查网络。仍可使用 JSON 导入导出。','Cannot reach the share service — check your network. JSON import/export still works.'));throw e;}finally{clearTimeout(timer);}}
async function copy(text){if(navigator.clipboard&&window.isSecureContext){try{await navigator.clipboard.writeText(text);return true;}catch{}}const t=document.createElement('textarea');t.value=text;t.style.cssText='position:fixed;left:0;top:0;opacity:0';(active||document.body).append(t);t.focus();t.select();let ok=false;try{ok=document.execCommand('copy');}finally{t.remove();}return ok;}
function preview(deck,cards){const map=Object.fromEntries(cards.map(c=>[c.key,c])),list=(keys)=>{const counts={};keys.forEach(k=>counts[k]=(counts[k]||0)+1);return Object.entries(counts).map(([k,n])=>`<span>${esc(map[k]?cardName(map[k]):k)} × ${n}</span>`).join('');};const sig=deck.heroes.flatMap(k=>map[k]?.signature?Array(3).fill(map[k].signature):[]);return `<h3>${esc(pick(deck,'name')||deck.name)}</h3><p>${T('英雄（顺序决定首发与入场）','Heroes (order sets deployment)')}</p><div class="deck-share-list">${deck.heroes.map((k,i)=>`<span>${i+1}. ${esc(map[k]?cardName(map[k]):k)}</span>`).join('')}</div><p>${T('主牌','Main deck')} ${deck.main.length+sig.length} ${T(' 张（含 ',' (incl. ')}${sig.length}${T(' 张英雄专属牌）',' signature cards)')}</p><div class="deck-share-list">${list([...deck.main,...sig])}</div><p>${T('物品牌','Items')} ${deck.items.length}</p><div class="deck-share-list">${list(deck.items)}</div>`;}
function share(deck,validate){const errors=validate(deck);if(errors.length)throw Error(errors[0]);const snapshot=JSON.parse(JSON.stringify(deck)),d=open(T('分享构筑','Share deck'));d.querySelector('[data-body]').innerHTML=`<p>${T('生成分享码后，其他玩家可在同一服务器导入此构筑。只分享当前牌组，不分享你的身份和对局。','After a share code is generated, other players on this server can import the build. Only the deck is shared — not your identity or match.')}</p>`;const b=action(d,T('生成分享码','Generate share code'),async()=>{b.disabled=true;status(d,T('正在生成…','Generating…'));try{const data=await request('/api/decks/share',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deck:snapshot})});if(!/^AFD-[A-Z0-9]{8}$/.test(data.code))throw Error(T('分享服务返回了无效的分享码','The share service returned an invalid code'));if(!d.isConnected)return;d.querySelector('[data-body]').innerHTML=`<p>${esc(pick(snapshot,'name')||snapshot.name)} · ${T('分享码','Share code')}</p><input class="deck-share-code" aria-label="${T('构筑分享码','Deck share code')}" readonly value="${esc(data.code)}"><p>${T('这是构筑分享码，不是 6 位房间匹配码。请在同一服务器的“导入分享码”中使用。','This is a deck share code, not a 6-character room code. Use “Import share code” on this server.')}</p>`;b.hidden=true;action(d,T('复制分享码','Copy share code'),async()=>{status(d,await copy(data.code)?T('分享码已复制。','Share code copied.'):T('自动复制失败，请选中上方分享码手动复制。','Auto-copy failed — select the code above to copy it.'));});status(d,T('已保存当前构筑快照；后续编辑不会改变此分享码。','A snapshot was saved — later edits will not change this code.'));}catch(e){status(d,e.message);b.disabled=false;}});action(d,T('关闭','Close'),()=>d.close());b.click();}
function importDeck({cards,validate,onConfirm,confirmLabel=T('导入到编辑器','Import into editor'),explanation=T('确认后替换当前编辑草稿；已保存构筑不变，需点击“保存牌组”才会覆盖。','Confirming replaces the current draft; your saved deck is unchanged until you click Save deck.')}){const d=open(T('导入构筑分享码','Import a deck share code'));d.querySelector('[data-body]').innerHTML=`<p>${T('输入好友提供的 AFD- 开头的构筑分享码；不填写房间匹配码。','Enter the AFD- share code a friend gave you — not a room match code.')}</p><input aria-label="${T('输入构筑分享码','Enter deck share code')}" placeholder="AFD-XXXXXXXX" maxlength="20" autocomplete="off" autocapitalize="characters">`;const input=d.querySelector('input');const b=action(d,T('预览构筑','Preview deck'),async()=>{const code=input.value.trim().toUpperCase();if(!/^AFD-[A-Z0-9]{8}$/.test(code)){status(d,T('请输入 AFD- 开头、后接 8 位字母或数字的构筑分享码。','Enter a share code: AFD- followed by 8 letters or digits.'));return;}b.disabled=true;status(d,T('正在读取…','Loading…'));try{const data=await request('/api/decks/share/'+encodeURIComponent(code));const errs=validate(data.deck);if(errs.length)throw Error(errs[0]);if(!d.isConnected)return;d.querySelector('[data-body]').innerHTML=preview(data.deck,cards)+`<p>${esc(explanation)}</p>`;b.hidden=true;status(d,T('请核对构筑后确认导入。','Check the deck, then confirm import.'));const confirm=action(d,confirmLabel,async()=>{confirm.disabled=true;try{await onConfirm(JSON.parse(JSON.stringify(data.deck)));d.close();}catch(e){status(d,e.message);confirm.disabled=false;}});}catch(e){status(d,e.message);b.disabled=false;}});action(d,T('取消','Cancel'),()=>d.close());input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();b.click();}});input.focus();}
function savedDecks(){try{const list=JSON.parse(localStorage.getItem('artifact.savedDecks')||'[]');return Array.isArray(list)?list:[];}catch{return [];}}
function saveDeck(deck){const snapshot={name:String(deck.name||T('收藏构筑','Saved build')).slice(0,80),heroes:[...deck.heroes],main:[...deck.main],items:[...deck.items]},list=savedDecks();const same=list.find(d=>JSON.stringify([d.heroes,d.main,d.items])===JSON.stringify([snapshot.heroes,snapshot.main,snapshot.items]));if(same)return same;const saved={...snapshot,id:'saved-'+Array.from(crypto.getRandomValues(new Uint8Array(12)),v=>v.toString(16).padStart(2,'0')).join('')};list.push(saved);localStorage.setItem('artifact.savedDecks',JSON.stringify(list));return saved;}
window.ArtifactDeckShare={share,importDeck,copy,savedDecks,saveDeck};
})();
